{
  "Version": "1.021",
  "ModID": "AIEnterSessionsAfterHuman_Serp",
  "IncompatibleIds": null,
  "ModDependencies": null,
  "LoadAfterIds":["Everyone_Hard_AI_Serp","KreitaniTaludas_Kingsgrove","Four_Crowns","Taludas_NewWorldExpanded_Mayabeque","NewHorizons"],
  "Category": {
    "English": "Gameplay",
    "German": "Gameplay"
  },
  "ModName": {
    "English": "AI Enters Sessions After Human, Asks Permission (Serp)",
    "German": "AI KI betritt Sessions nach Spieler, fragt Erlaubnis (Serp)"
  },
  "Description": {
    "English": "All AIs asking for Settlement Permission (except if at war). Adjusted the reputation changes from +-5 for accept/decline to +3-1 for easy, +-2 for medium and +1-3 for hard AI. Keeps the vanilla conditions for AIs (like unlocking windows before entering New World), but adds the condition that the human player (Human0=Host) must own a harbour first in that session. This way the AI never enters a session before the player. Supports Mod sessions.",
    "German": "Alle KIs fragen nach Besiedelungs Erlaubnis (außer wenn man im Krieg mit ihr ist). Die Meinungsänderungen wurde geändert von +-5 für Erlauben/Verbieten zu +3-1 für leichte, +-2 für mittlere und +1-3 für schwere KI. Behält die vanilla Bedingnungen für die KI bei (wie freischalten von Fenstern um die neue Welt betreten zu können) und fügt die Bedingung hinzu, dass der menschliche Spieler (Human0=Host) in der Session einen Kontor besitzen muss. So ist die KI niemals vor dem Spieler in einer Session. Gilt auch für Mod Sessions."
  },
  "KnownIssues": [
    {
      "English": null,
      "German": null
    }
  ],
  "DLCDependencies": null,
  "CreatorName": "Serp",
  "CreatorContact": "https://github.com/Serpens66",
  "ModioResourceId": 3689240,
  "changelog": {
    "1.021" : "Add ModioResourceId to modinfo.json"
  }
}

