  "LoadAfterIds": ["*","Community_Patch"],
  "Category": {
    "English": "Shared",
    "German": "Shared"
  },
  "ModName": {
    "English": "Copy Pools CP Kontors+Ships+Airships",
    "German": "Copy Pools CP Kontors+Ships+Airships"
  },
  "Description": {
    "English": "For Modders: Should load last and then eg. copy a PlayerCounterContextPool into an ItemEffectTargetPool or other pool conversions, after modders added their stuff to existing pools. Because such code loads long, I divide it into multiple shared mods, one per topic, so a mod using this can use the specific pools they need.",
    "German": "Für Modder: Sollte als Letztes laden und kopiert dann zb den Inhalt eines PlayerCounterContextPool in einen neuen ItemEffectTargetPool oder andere Pool Umwandlungen, nachdem Modder ihr zeug zu existierenden Pools zugefügt haben. Da solch ein Code sehr lange läd, teile ich es in mehrere shared mods auf, damit die mods speziell den shared mod nutzen können den sie brauchen."
  },
  "DLCDependencies": null,
  "CreatorName": "Serp",
  "CreatorContact": "https://github.com/Serpens66"
}

{
  "Version": "1.001",
  "ModID": "Permanent_Piratemode_Item_Serp",
  "IncompatibleIds": null,
  "ModDependencies": null,
  "Category": {
    "Chinese": "游戏玩法",
    "English": "Gameplay",
    "German": "Gameplay"
  },
  "ModName": {
    "English": "Item: Permanent Piratemode (Serp)",
    "German": "Item: Permanenter Piratenmodus (Serp)"
  },
  "Description": {
    "English": "Adds a new legendary pirateflag, which grants the equipping ship permanent pirate mode as long it is equipped. Eg. useful to equip your Flak ships with it to prevent anyone to drop propaganda on your islands. The item is added to the legendary rewardpool of pirates, see ingame item-statistics for details how to get them. If you have my mod -P Reward Destroy Pirate (Serp)- active, it can also drop as reward from destroying the pirates.",
    "German": "Fügt eine legendäre Piratenflagge hinzu, welche das ausgerüstete Schiff solange sie ausgerüstet ist, dauerhaft in den Piratenmodus versetzt. Zb. sinnvoll um Flak Schiffe auszurüsten, um zu verhindern das jemand Propaganda mit Luftschiffen verteilt. Ist Teil der Legendary RewardPools der Piraten, siehe die Item-Statistik im Spiel für genaueres. Wenn mein Mod -P Reward Destroy Pirate (Serp)- aktiv ist, kann es auch als Belohnung für die Zerstörung der Piraten droppen."
  },
  "DLCDependencies": null,
  "CreatorName": "Serp",
  "CreatorContact": "https://github.com/Serpens66",
  "ModioResourceId": 3606208,
  "changelog": {
    "1.001" : "Add ModioResourceId to modinfo.json"
  }
}

